def shapes(g):
    # cluster 2-cells connected (8-conn) 
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==2 and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));comp=[]
                while st:
                    a,b=st.pop();comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<h and 0<=y<w and g[x][y]==2 and (x,y) not in seen:
                                seen.add((x,y));st.append((x,y))
                out.append(sorted(comp))
    return out
