def f(g, minlen=2):
    o=[r[:] for r in g]
    cs=comps4(g)
    lab={id(c):i for i,c in enumerate(cs)}
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=0: continue
            # horizontal: consecutive 2s flanking, different comps, gap>=minlen
            left=g[r][c-1]==2
            right=g[r][c+1]==2
            if left and right:
                L=min(lab[id(c)] for c2 in range(c-1,-1,-1) if g[r][c2]==2)
                R=min(lab[id(c)] for c2 in range(c+1,len(g[0])) if g[r][c2]==2)
                if L!=R:
                    ok=True
                    for k2 in range(c,L+1):
                        if g[r][k2]!=2: ok=False;break
                    for k2 in range(c+1,R+1):
                        if g[r][k2]!=2: ok=False;break
                    if ok and (R-L-1)>=minlen:
                        for k2 in range(c,R+1): o[r][k2]=1 if g[r][k2]==0 else g[r][k2]
    for c in range(len(g[0])):
        for r in range(len(g)):
            up=g[r-1][c]==2 if r>0 else False
            dn=g[r+1][c]==2 if r<len(g)-1 else False
            if up and dn:
                T=min(lab[id(c)] for r2 in range(r-1,-1,-1) if g[r2][c]==2)
                B=min(lab[id(c)] for r2 in range(r+1,len(g)) if g[r2][c]==2)
                if T!=B:
                    ok=True
                    for r2 in range(r,B+1):
                        if g[r2][c]!=2: ok=False;break
                    for r2 in range(T+1,r+1):
                        if g[r2][c]!=2: ok=False;break
                    if ok and (B-T-1)>=minlen:
                        for r2 in range(T,B+1): o[r2][c]=1 if g[r2][c]==0 else g[r2][c]
    return o
