def solve(I):
    H,W=len(I),len(I[0])
    O=[row[:] for row in I]
    pts={(r,c) for r in range(H) for c in range(W) if I[r][c]==2}
    offs=[(a,b) for a in(-1,0,1) for b in(-1,0,1) if abs(a)+abs(b)==2]
    seen=set(); comps=[]
    for p in sorted(pts):
        if p in seen: continue
        st=[p]; seen.add(p); c_=[]
        while st:
            q=st.pop(); c_.append(q)
            for o in offs:
                pp=(q[0]+o[0],q[1]+o[1])
                if pp in pts and pp not in seen:
                    seen.add(pp); st.append(pp)
        comps.append(c_)
    def cent(cp): return (sum(r for r,_ in cp)/len(cp), sum(v for _,v in cp)/len(cp))
    # horizontal pair on same row: pick the two extreme cells in that row across comps
    for cp,qq in itertools.combinations(comps,2):
        rows_c={r for r,_ in cp}; rows_q={r for r,_ in qq}
        common_row = rows_c & rows_q
        if len(common_row)!=1: continue
        r_=sorted(common_row)[0]
        ac=sorted((c for rr,c in cp if rr==r_), key=lambda c: c)
        bq=sorted((c for rr,c in qq if rr==r_), key=lambda c: c)
        if not ac or not bq: continue
        a_min,a_max=min(ac),max(ac); b_min,b_max=min(bq),max(bq)
        # which cells stick out: the outer extremes
        ca,cb=a_max,b_min
        # condition: a_max is farther right than a_min relative? decide: endpoints must be on OPPOSITE sides of their own centroids along the line
        cr_a=sum(c for rr,c in cp)/len(cp); cr_b=sum(c for rr,c in qq)/len(qq)
        if (ca-cr_a)*(cb-cr_b)<0:
            x=range(min(ca,cb)+1,max(ca,cb))
            for x_ in x:
                if O[r_][x_]==0: O[r_][x_]=1
        else:
            # opposite sides -> they face each other? careful
            pass
    return O
