        for c in set(c for _,c in A)&set(c for _,c in B):
            sa=sorted(r for r,cc in A if cc==c); sb=sorted(r for r,cc in B if cc==c)
            for a_,b_ in zip(sa,sb):
                segs.append(('v',c,a_,b_))
