    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(I):
    pts={(r,c) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]==2}
    offs=[(a,b) for a in(-1,0,1) for b in(-1,0,1) if abs(a)+abs(b)==2]
    seen=set(); comps=[]
    for p in sorted(pts):
        if p in seen: continue
        st=[p]; seen.add(p); c_=[]
        while st:
            q=st.pop(); c_.append(q)
            for o in offs:
                pp=(q[0]+o[0],q[1]+o[1])
                if pp in pts and pp not in seen:
                    seen.add(pp); st.append(pp)
        comps.append(frozenset(c_))
    return comps
def f(I):
    O=[row[:] for row in I]
    cs=comps_of(I)
    # centers
    cen=[(sum(r for r,_ in A)/len(A), sum(c for _,c in A)/len(A)) for A in cs]
    # candidates: pairs with |cr diff|<=0.5 or |cc diff|<=0.5 AND aligned axis
    for i,j in itertools.combinations(range(len(cs)),2):
        ca,cb=cen[i],cen[j]
        if abs(ca[0]-cb[0])<=0.5 and abs(ca[1]-cb[1])>0.5:   # same row band -> horizontal
            rr=int(round(ca[0]))
            # extreme cells in that row band on each side
            la=max(c for r,c in cs[i] if abs(r-rr)<=1)
            lb=min(c for r,c in cs[j] if abs(r-rr)<=1)
            seg=list(range(la+1,lb))
            if all(I[rr][x]==0 for x in seg):
                for x in seg: O[rr][x]=1
        elif abs(ca[1]-cb[1])<=0.5 and abs(ca[0]-cb[0])>0.5:
            cc=int(round(ca[1]))
            ta=max(r for r,c in cs[i] if abs(c-cc)<=1)
            tb=min(r for r,c in cs[j] if abs(c-cc)<=1)
            seg=list(range(ta+1,tb))
            if all(I[x][cc]==0 for x in seg):
                for x in seg: O[x][cc]=1
        else:
            continue
    return O
